targets.query:
let operations = MetricSeriesRate('mysql.file_io', 'operations_total', '$run_id', $__timeFrom, $__timeTo)
| project Timestamp, TargetId, SeriesKey, Mode=tostring(Tags.mode), Operations=Rate;
let waits = MetricSeriesRate('mysql.file_io', 'wait_ms_total', '$run_id', $__timeFrom, $__timeTo)
| project Timestamp, TargetId, SeriesKey, WaitMs=Rate;
operations
| where TargetId in ($target_id) and Mode in ('read', 'write')
| join kind=inner waits on Timestamp, TargetId, SeriesKey
| summarize Operations=sum(Operations), WaitMs=sum(WaitMs) by Timestamp, TargetId, Mode
| where Operations > 0
| extend LatencyMs=WaitMs / Operations, Series=strcat(TargetId, ' / ', Mode)
| project Timestamp, Series, LatencyMs
| order by Timestamp asc

let operations = MetricSeriesRate('mysql.file_io', 'operations_total', '$run_id', $__timeFrom, $__timeTo)
| where TargetId in ($target_id)
| summarize IOPS=avg(Rate), Operations=sum(Delta) by TargetId, SeriesKey, Event=tostring(Tags.event), Mode=tostring(Tags.mode);
let waits = MetricSeriesRate('mysql.file_io', 'wait_ms_total', '$run_id', $__timeFrom, $__timeTo)
| where TargetId in ($target_id)
| summarize WaitMs=sum(Delta) by TargetId, SeriesKey;
operations
| join kind=inner waits on TargetId, SeriesKey
| extend AvgLatencyMs=iff(Operations > 0, WaitMs / Operations, 0.0)
| order by WaitMs desc
| project TargetId, Event, Mode, IOPS=round(IOPS, 2), AvgLatencyMs=round(AvgLatencyMs, 3), Operations
| take 100
